28	    let mut watcher = Watcher::new(Some(output.clone()))?;
29	
30	    // Create the world that serves sources, files, and fonts.
31	    // Additionally, if any files do not exist, wait until they do.
32	    let mut world = loop {
33	        match SystemWorld::new(
34	            Some(&command.args.input),
35	            &command.args.world,
36	            &command.args.process,
37	        ) {
38	            Ok(world) => break world,
39	            Err(
40	                ref err @ (WorldCreationError::InputNotFound(ref path)
41	                | WorldCreationError::RootNotFound(ref path)),
42	            ) => {
43	                watcher.update([path.clone()])?;
44	                Status::Error.print(&config).unwrap();
45	                print_error(&err.to_string()).unwrap();
46	                watcher.wait()?;
47	            }
48	            Err(err) => return Err(err.into()),
49	        }
50	    };
51	
52	    // Eagerly scan fonts if we expect to need them so that it's not counted as
53	    // part of the displayed compilation time. The duration of font scanning is
54	    // heavily system-dependent, so it could result in confusion why compilation
55	    // is so much faster/slower.
56	    if config.output_format.is_paged() {
57	        world.scan_fonts();
58	    }
59	
60	    // Perform initial compilation.
61	    timer.record(&mut world, |world| compile_once(world, &mut config))??;
62	
63	    // Print warning when trying to watch stdin.
64	    if matches!(&config.input, Input::Stdin) {
65	        warn_watching_std(&world, &config)?;
66	    }
67	
68	    // Recompile whenever something relevant happens.
69	    loop {
70	        // Watch all dependencies of the most recent compilation.
71	        watcher.update(world.dependencies())?;
72	
73	        // Wait until anything relevant happens.
74	        watcher.wait()?;
75	
76	        // Reset all dependencies.
77	        world.reset();
78	
79	        // Recompile.
80	        timer.record(&mut world, |world| compile_once(world, &mut config))??;
81	
82	        // Evict the cache.
83	        comemo::evict(10);
84	    }
85	}
86	
87	/// The status in which the watcher can be.
88	pub enum Status {
89	    Compiling,
90	    Success(std::time::Duration),
91	    PartialSuccess(std::time::Duration),
92	    Error,
93	}
94	
95	impl Status {
96	    /// Clear the terminal and render the status message.
97	    pub fn print(&self, config: &CompileConfig) -> io::Result<()> {
98	        let mut out = terminal::out();
99	
100	        if config.fullscreen {
101	            self.print_fullscreen(&mut out, config)?;
102	        } else {
103	            self.print_message(&mut out)?;
104	            if !matches!(self, Status::Compiling) {
105	                writeln!(out)?;
106	            }
107	        }
108	
109	        out.flush()
110	    }
111	
112	    fn print_fullscreen(
113	        &self,
114	        out: &mut TermOut,
115	        config: &CompileConfig,
116	    ) -> io::Result<()> {
117	        let color = self.color();
118	        out.clear_screen()?;
119	
120	        out.set_color(&color)?;
121	        write!(out, "watching")?;
122	        out.reset()?;
123	        match &config.input {
124	            Input::Stdin => writeln!(out, " <stdin>"),
125	            Input::Path(path) => writeln!(out, " {}", path.display()),
126	        }?;
127	
128	        out.set_color(&color)?;
129	        write!(out, "writing to")?;
130	        out.reset()?;
131	        writeln!(out, " {}", config.output)?;
132	
133	        #[cfg(feature = "http-server")]
134	        if let Some(server) = &config.server {
135	            out.set_color(&color)?;
136	            write!(out, "serving at")?;
137	            out.reset()?;
138	            writeln!(out, " http://{}", server.addr())?;
139	        }
140	
141	        writeln!(out)?;
142	        self.print_message(out)?;
143	        writeln!(out)?;
144	
145	        Ok(())
146	    }
147	
148	    fn print_message(&self, out: &mut TermOut) -> io::Result<()> {
149	        let timestamp = chrono::offset::Local::now().format("%H:%M:%S");
150	        writeln!(out, "[{timestamp}] {}", self.message())
151	    }
152	
153	    fn message(&self) -> String {
154	        match *self {
155	            Self::Compiling => "compiling ...".into(),
156	            Self::Success(duration) => {
157	                format!("compiled successfully in {}", format_duration(duration))
158	            }
159	            Self::PartialSuccess(duration) => {
160	                format!("compiled with warnings in {}", format_duration(duration))
161	            }
162	            Self::Error => "compiled with errors".into(),
163	        }
164	    }
165	
166	    fn color(&self) -> termcolor::ColorSpec {
167	        let styles = term::Styles::default();
168	        match self {
169	            Self::Error => styles.header_error,
170	            Self::PartialSuccess(_) => styles.header_warning,
171	            _ => styles.header_note,
172	        }
173	    }
174	}
175	
176	/// Emits a warning when trying to watch stdin.
177	fn warn_watching_std(world: &SystemWorld, config: &CompileConfig) -> StrResult<()> {
178	    let warning = warning!(
179	        Span::detached(),
180	        "cannot watch changes for stdin";
181	        hint: "to recompile on changes, watch a regular file instead";
182	        hint: "to compile once and exit, please use `typst compile` instead";
183	    );
184	    print_diagnostics(world, &[], &[warning], config.diagnostic_format)
185	        .map_err(|err| eco_format!("failed to print diagnostics ({err})"))
186	}
