37	    /// watching.
38	    const BATCH_TIMEOUT: Duration = Duration::from_millis(100);
39	
40	    /// The maximum time we spend batching events before quitting `wait()`.
41	    const STARVE_TIMEOUT: Duration = Duration::from_millis(500);
42	
